+import { LINEAR_UNITS, TEMPERATURE_UNITS } from "./units.ts";
+
 /** Convert `value` from one unit to another of the same kind. See README.md. */
 export function convert(value: number, from: string, to: string): number {
-  throw new Error("not implemented");
+  // Check if both units are the same
+  if (from === to) {
+    return value;
+  }
+
+  // Handle temperature conversions
+  const isFromTemp = TEMPERATURE_UNITS.includes(from as any);
+  const isToTemp = TEMPERATURE_UNITS.includes(to as any);
+  
+  if (isFromTemp && isToTemp) {
+    // Check for temperatures below absolute zero
+    if (from === "C" && value < -273.15) {
+      throw new RangeError(`below absolute zero: ${value} ${from}`);
+    }
+    if (from === "F" && value < -459.67) {
+      throw new RangeError(`below absolute zero: ${value} ${from}`);
+    }
+    if (from === "K" && value < 0) {
+      throw new RangeError(`below absolute zero: ${value} ${from}`);
+    }
+
+    // Convert to Celsius first
+    let celsius: number;
+    if (from === "C") {
+      celsius = value;
+    } else if (from === "F") {
+      celsius = (value - 32) * 5 / 9;
+    } else { // from === "K"
+      celsius = value - 273.15;
+    }
+
+    // Convert from Celsius to target unit
+    if (to === "C") {
+      return celsius;
+    } else if (to === "F") {
+      return celsius * 9 / 5 + 32;
+    } else { // to === "K"
+      return celsius + 273.15;
+    }
+  }
+
